  if not exists (select 1 from public.plataformas p where p.slug = 'tangiblex' and p.slug::text = 'tangiblex' and p.nombre::text = 'TangibleX' and p.estado::text = 'en_radar' and p.categoria_slug::text = 'inmobiliario' and p.region_slug::text = 'asia-pacifico' and p.actor::text = 'Marketplace' and p.acceso::text = 'Minorista' and p.ticket::text = 'Bajo' and p.cadenas::text = 'No la publica' and p.web::text = 'https://www.tangiblex.com.au/' and p.aval::text = 'Mercado australiano de participaciones tokenizadas de fondos; cada producto que lista lo origina una gestora con licencia AFSL, según su web.' and p.nota::text = 'Participaciones de fondos y planes de inversión australianos representadas con tokens, para inversores verificados.') then
    raise exception 'La plataforma tangiblex no quedó como se esperaba.';
  end if;
  if not exists (select 1 from public.plataformas p where p.slug = 'caliber' and p.slug::text = 'caliber' and p.nombre::text = 'Caliber' and p.estado::text = 'en_radar' and p.categoria_slug::text = 'inmobiliario' and p.region_slug::text = 'ee-uu' and p.actor::text = 'Emisor' and p.acceso::text = 'Acreditado' and p.ticket::text = 'Alto' and p.cadenas::text = 'No la publica' and p.web::text = 'https://www.caliberco.com/caliber-goes-live-with-tokenization-of-three-more-real-estate-offerings/' and p.aval::text = 'CaliberCos Inc., gestora inmobiliaria estadounidense, ha tokenizado tres ofertas más: dos promociones de hoteles y un fondo.' and p.nota::text = 'Participaciones tokenizadas de ofertas inmobiliarias de Caliber en EE. UU. (hoteles y fondos).') then
    raise exception 'La plataforma caliber no quedó como se esperaba.';
  end if;
  if not exists (select 1 from public.plataformas p where p.slug = 'okxice' and p.slug::text = 'okxice' and p.nombre::text = 'OKXICE' and p.estado::text = 'en_radar' and p.categoria_slug::text = 'acciones-y-capital-privado' and p.region_slug::text = 'ee-uu' and p.actor::text = 'Marketplace' and p.acceso::text = 'Minorista' and p.ticket::text = 'Bajo' and p.cadenas::text = 'Ethereum (X Layer)' and p.web::text = 'https://www.okx.com/en-eu/learn/okxice-tsv-launch-going-live' and p.aval::text = 'Mercado de valores tokenizados de OKX e ICE abierto el 23/11/2026, solo para clientes de OKX Inc. en EE. UU. que cumplan los requisitos.' and p.nota::text = 'Acciones y ETF de EE. UU. tokenizados que se negocian las 24 horas en X Layer, la red de OKX.') then
    raise exception 'La plataforma okxice no quedó como se esperaba.';
  end if;
  if (select count(*) from public.plataformas where estado = 'en_radar') <> 57
    or (select count(*) from public.plataformas where estado = 'descartada') <> 5 then
    raise exception 'Cuentas del radar inesperadas tras las altas.';
  end if;
end $publico_comprobar$;

do $aprobar$
declare v uuid := '7f745c7d-5a25-2385-9e6c-d855a22c9d02';
begin
  if (select count(*) from rwadar_catalogo.plataformas where revision_id = v) <> 57
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v) <> 32
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'principales') <> 17
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'secundario') <> 13
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'en_camino') <> 2
    or (select count(*) from rwadar_catalogo.plataformas c join public.plataformas p on p.id = c.plataforma_id
      where c.revision_id = v and p.slug in ('raiz', 'tokeniza', 'etherfuse', 'hator', 'real-tokn', 'bloktok', 'bit2me-stx', 'assetera', 'estating', 'seturion', 'digishares', 'ctrl-alt', 'digift', 'sdax', 'terazo', 'tokinvest', 'prypco-mint', 'mesh', 'oaksvale', 'cradle', 'shard', 'luxivana', 'tangiblex', 'caliber', 'okxice')) <> 25 then
    raise exception 'Catálogo incompleto: se conserva el lote anterior';
  end if;
  update rwadar_catalogo.revisiones set estado = 'aprobada', aprobada_el = now(),
    aprobada_referencia = 'Entrega 2026-11-26.4: 25 plataformas del radar del informe global del 26/11/2026, comprobadas en su propia web ese día. 57 plataformas y 32 ofertas (17/13/2); el resto, igual a la 2026-11-26.3. Puesta al día pedida por el responsable del proyecto el 26/11/2026.'
    where id = v and estado = 'borrador';
  if not exists (select 1 from rwadar_catalogo.revision_publicable_v2 where id = v) then
    raise exception 'Entrega no publicable: se deshace la transacción completa';
  end if;
  if (select revision_id from rwadar_catalogo.publicacion_v2 where unica) is distinct from v then
    raise exception 'La revisión nueva no quedó publicada: se deshace la transacción completa';
  end if;
end $aprobar$;
commit;
