insert into rwadar_catalogo.alertas (revision_id,plataforma_id,codigo,detalle) select '7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,id,'terminos_finales_no_confirmados','Que el folleto esté «aprobado por la FMA» no es un aval ni una licencia de Midas: según el folleto base del 17/07/2026, la FMA solo revisa que esté completo, se entienda y sea coherente, y el emisor no queda regulado por ella. Si pueden entrar minoristas del EEE lo deciden las condiciones finales de mTBILL; las del 17/07/2026 no lo prohíben, pero eso no confirma que la web te deje darte de alta.' from public.plataformas where slug='midas' on conflict do nothing;
