insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'tohkn-iber1','rendimiento','IBER1: deuda tokenizada de Iberplastic al 7 % fijo anual (El Salvador)','tohkn','TOHKN','credito-privado','SV','Primer tramo de deuda digital de Iberplastic, fabricante salvadoreño de productos de limpieza con material reciclado: 7,00 % fijo anual, intereses cada mes y devolución a los 24 meses. Se compra solo en la app de TOHKN.','https://www.tohkn.com/en/issuances/iber1','2026-11-26'::date,7,false,null,false,true,null,'{"mostrada":"7,00 %","literal":"Interés fijo anual del primer tramo, pagado cada mes, según TOHKN (consultado el 26/11/2026). Lo promete el emisor: si Iberplastic no paga, puedes perder lo invertido."}'::jsonb,null,'[{"etiqueta":"Mínimo","valor":"100 USD (1 token)"},{"etiqueta":"Emisor","valor":"Iberplastic, S.A. de C.V. (El Salvador)"},{"etiqueta":"Plazo","valor":"24 meses (primer tramo); capital al vencimiento"},{"etiqueta":"Intereses","valor":"Cada mes, en USDT o USDC"},{"etiqueta":"Importe","valor":"2.000.000 USD el primer tramo (hasta 4.000.000 USD autorizados)"},{"etiqueta":"Registro","valor":"Oferta pública de activos digitales en El Salvador (CNAD); token ERC-3643 en Polygon"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Emisión registrada en El Salvador, no en la UE: sin folleto ni KID europeos y sin supervisión de la CNMV.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Es deuda de una sola empresa: si Iberplastic no paga, puedes perder parte o todo.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"TOHKN no publica qué países admite: comprueba en su app si puedes invertir desde donde vives.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Cobras en USDT o USDC (stablecoins en dólares): hay riesgo de cambio y riesgo de la stablecoin.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Solo se puede vender antes del vencimiento si TOHKN habilita un secundario; la liquidez no está asegurada.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://www.tohkn.com/en/issuances/iber1","https://www.tohkn.com/en/issuances","https://www.tohkn.com/en/legal/terms-and-conditions"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Deuda digital (token de deuda) de Iberplastic, S.A. de C.V., fabricante salvadoreño fundado en 1997. El primer tramo, de 2.000.000 USD, paga un 7,00 % fijo anual con intereses mensuales y devuelve el capital a los 24 meses. Los fondos se destinan a ampliar sus plantas de reciclaje. Se invierte desde 100 USD solo en la app de TOHKN, tras verificar la identidad; los pagos se hacen en USDT o USDC.","fuentes":["https://www.tohkn.com/en/issuances/iber1","https://www.tohkn.com/en/issuances","https://www.tohkn.com/en/legal/terms-and-conditions"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"TOHKN (MIO3, S.A. de C.V.)"},{"etiqueta":"Emisor","valor":"Iberplastic, S.A. de C.V."},{"etiqueta":"Qué se adquiere","valor":"Un derecho de cobro de capital e intereses frente a Iberplastic; no da propiedad de la empresa ni votos"},{"etiqueta":"Moneda","valor":"USD (pagos en USDT o USDC)"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Desde 100 USD (1 token)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/iber1","alcance":"Resumen de la oferta en la ficha de IBER1 de TOHKN."},{"etiqueta":"Acceso desde España","valor":"Sin confirmar: TOHKN no publica qué países admite","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/legal/terms-and-conditions","alcance":"Sus condiciones excluyen jurisdicciones restringidas sin publicar la lista."},{"etiqueta":"Salida","valor":"Al vencimiento (24 meses); antes, solo si TOHKN abre un mercado secundario","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/iber1","alcance":"Ficha de IBER1: la liquidez no está garantizada."},{"etiqueta":"Rentabilidad publicada","valor":"7,00 % fijo anual (primer tramo)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/iber1","alcance":"Interés fijo del primer tramo, pagado cada mes."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'tohkn-mmlti1','rendimiento','MMLTI1: deuda tokenizada de MultiMoney al 6,20 % fijo anual (El Salvador)','tohkn','TOHKN','credito-privado','SV','Primer tramo del programa de deuda digital de MultiMoney, sociedad salvadoreña de ahorro y crédito: 6,20 % fijo anual, intereses cada mes y devolución a los 24 meses. Se compra solo en la app de TOHKN.','https://www.tohkn.com/en/issuances/mmlti1','2026-11-26'::date,7,false,null,false,true,null,'{"mostrada":"6,20 %","literal":"Interés fijo anual del primer tramo, pagado cada mes, según TOHKN (consultado el 26/11/2026). Lo promete el emisor: si MultiMoney no paga, puedes perder lo invertido."}'::jsonb,null,'[{"etiqueta":"Mínimo","valor":"100 USD (1 token)"},{"etiqueta":"Emisor","valor":"Sociedad de Ahorro y Crédito Multimoney, S.A. (El Salvador)"},{"etiqueta":"Plazo","valor":"24 meses (primer tramo); capital al vencimiento"},{"etiqueta":"Intereses","valor":"Cada mes"},{"etiqueta":"Importe","valor":"Hasta 2.000.000 USD el primer tramo (programa MMY de hasta 10.000.000 USD)"},{"etiqueta":"Registro","valor":"Oferta pública de activos digitales en El Salvador (CNAD); token ERC-3643 en Polygon"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Emisión registrada en El Salvador, no en la UE: sin folleto ni KID europeos y sin supervisión de la CNMV.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Es deuda de una sola entidad: si MultiMoney no paga, puedes perder parte o todo.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"TOHKN no publica qué países admite: comprueba en su app si puedes invertir desde donde vives.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Precio y pagos en dólares: riesgo de cambio frente al euro.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Solo se puede vender antes del vencimiento si TOHKN habilita un secundario; la liquidez no está asegurada.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://www.tohkn.com/en/issuances/mmlti1","https://www.tohkn.com/en/issuances","https://www.tohkn.com/en/legal/terms-and-conditions"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Deuda digital del programa MMY de la Sociedad de Ahorro y Crédito Multimoney, S.A. (El Salvador). El primer tramo, de hasta 2.000.000 USD, paga un 6,20 % fijo anual con intereses mensuales y devuelve el capital a los 24 meses; el dinero financia el crecimiento de su cartera de créditos. Se invierte desde 100 USD solo en la app de TOHKN, tras verificar la identidad.","fuentes":["https://www.tohkn.com/en/issuances/mmlti1","https://www.tohkn.com/en/issuances","https://www.tohkn.com/en/legal/terms-and-conditions"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"TOHKN (MIO3, S.A. de C.V.)"},{"etiqueta":"Emisor","valor":"Sociedad de Ahorro y Crédito Multimoney, S.A."},{"etiqueta":"Qué se adquiere","valor":"Un derecho de cobro de capital e intereses frente a MultiMoney, según el programa de emisión"},{"etiqueta":"Moneda","valor":"USD"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Desde 100 USD (1 token)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/mmlti1","alcance":"Resumen de la oferta en la ficha de MMLTI1 de TOHKN."},{"etiqueta":"Acceso desde España","valor":"Sin confirmar: TOHKN no publica qué países admite","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/legal/terms-and-conditions","alcance":"Sus condiciones excluyen jurisdicciones restringidas sin publicar la lista."},{"etiqueta":"Salida","valor":"Al vencimiento (24 meses); antes, solo si TOHKN abre un mercado secundario","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/mmlti1","alcance":"Ficha de MMLTI1 de TOHKN."},{"etiqueta":"Rentabilidad publicada","valor":"6,20 % fijo anual (primer tramo)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/mmlti1","alcance":"Interés fijo del primer tramo, pagado cada mes."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'tohkn-rncrrev','rendimiento','Renacer Condominio: ingresos por la venta de pisos en San Salvador (RNCRrev)','tohkn','TOHKN','inmobiliario','SV','Token de ingresos ligado a las ventas de un condominio residencial en San Salvador: el promotor apunta a una TIR del 15 % al 20 % en unos 29 meses, sin garantía. Se compra solo en la app de TOHKN.','https://www.tohkn.com/en/issuances/rncrrev','2026-11-26'::date,7,false,null,false,false,null,null,null,'[{"etiqueta":"Mínimo","valor":"100 USD (1 token)"},{"etiqueta":"Emisor","valor":"Desarrolladora Orizaba S.A. de C.V. (El Salvador)"},{"etiqueta":"Qué se adquiere","valor":"Derechos económicos sobre lo que se cobre por la venta de las viviendas"},{"etiqueta":"TIR objetivo del promotor","valor":"15 % a 20 % (objetivo, no garantizado)"},{"etiqueta":"Plazo estimado","valor":"29 meses, sujeto a que se termine el proyecto"},{"etiqueta":"Importe objetivo","valor":"7.000.000 USD"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Emisión registrada en El Salvador, no en la UE: sin folleto ni KID europeos y sin supervisión de la CNMV.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"La TIR es un objetivo del promotor: si el proyecto se retrasa o las viviendas se venden peor, puedes ganar menos o perder parte o todo.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"No compras viviendas: compras un derecho a parte de lo que se cobre al venderlas.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"TOHKN no publica qué países admite: comprueba en su app si puedes invertir desde donde vives.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://www.tohkn.com/en/issuances/rncrrev","https://www.tohkn.com/en/issuances","https://www.tohkn.com/en/legal/terms-and-conditions"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Token de ingresos de Renacer Condominio, un proyecto residencial de Desarrolladora Orizaba en San Salvador. Da derechos económicos sobre los flujos de la venta de las viviendas; el promotor apunta a una TIR del 15 % al 20 % en un plazo estimado de 29 meses, sujeto a que el proyecto se termine. Se invierte desde 100 USD solo en la app de TOHKN.","fuentes":["https://www.tohkn.com/en/issuances/rncrrev","https://www.tohkn.com/en/issuances","https://www.tohkn.com/en/legal/terms-and-conditions"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"TOHKN (MIO3, S.A. de C.V.)"},{"etiqueta":"Emisor","valor":"Desarrolladora Orizaba S.A. de C.V."},{"etiqueta":"Qué se adquiere","valor":"Derechos económicos sobre los flujos de venta de las viviendas; no la propiedad"},{"etiqueta":"Moneda","valor":"USD"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Desde 100 USD (1 token)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/rncrrev","alcance":"Resumen de la oferta en la ficha de RNCRrev de TOHKN."},{"etiqueta":"Acceso desde España","valor":"Sin confirmar: TOHKN no publica qué países admite","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/legal/terms-and-conditions","alcance":"Sus condiciones excluyen jurisdicciones restringidas sin publicar la lista."},{"etiqueta":"Salida","valor":"Cuando se vendan las viviendas (unos 29 meses, sin fecha cierta)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.tohkn.com/en/issuances/rncrrev","alcance":"Ficha de RNCRrev: plazo estimado y sujeto a terminar el proyecto."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'liqi-creditos-empresas','rendimiento','Liqi: 7 emisiones de crédito a empresas brasileñas en captación (20,98 % anual en reales)','liqi','Liqi','credito-privado','BR','Siete emisiones tokenizadas de crédito a empresas brasileñas (certificados de recebíveis) abiertas en Liqi, todas al 20,98 % anual en reales, con vencimientos entre abril de 2027 y mayo de 2028.','https://tokens.liqi.com.br/tokens','2026-11-26'::date,7,false,null,false,true,null,'{"mostrada":"20,98 %","literal":"Rentabilidad anual en reales que muestra Liqi para los 7 tramos en captación (equivale al 149,26 % del CDI brasileño), consultada el 26/11/2026. No es neta, no está en euros y no está garantizada."}'::jsonb,null,'[{"etiqueta":"Tramos en captación","valor":"PEDUUNQ09 (Principia, vence 04/12/2027) · PSALES01UNQ06 (Paysales, 02/06/2027) · MTGINCUNQ17 (Lebasq Invest, 07/05/2027) · SCUNQ20 (Smart Compass, 20/04/2027) · CLFIXUNQ17 (Clubtech, 26/06/2027) · STBROUNQ13 (Starbro Sport Tech, 26/05/2028) · MOV2UNQ13 (Movens, 12/05/2027)"},{"etiqueta":"Instrumento","valor":"Certificado de recebíveis (CR), régimen de financiación participativa CVM 88"},{"etiqueta":"Precio por unidad","valor":"R$ 25,00 (PEDUUNQ09)"},{"etiqueta":"Moneda","valor":"Reales brasileños (BRL)"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Emisiones brasileñas en reales, sin folleto ni KID europeos; la CNMV no las supervisa.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Son créditos a empresas pequeñas: si una no paga, puedes perder parte o todo lo invertido en ese tramo.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"La cifra es en reales y antes de impuestos; con la inflación y el cambio frente al euro, lo que cobres en euros puede ser mucho menor.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Liqi no publica si admite inversores que no residan en Brasil.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"No consta un mercado secundario: cuenta con esperar al vencimiento.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://tokens.liqi.com.br/tokens","https://tokens.liqi.com.br/tokens/PEDU?tranche=PEDUUNQ09"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Liqi coloca emisiones tokenizadas de crédito (certificados de recebíveis) de empresas brasileñas bajo la Resolución CVM 88. El 26/11/2026 tenía siete tramos en captación, todos al 20,98 % anual en reales (149,26 % del CDI): PEDUUNQ09 (Principia), PSALES01UNQ06 (Paysales), MTGINCUNQ17 (Lebasq Invest), SCUNQ20 (Smart Compass), CLFIXUNQ17 (Clubtech), STBROUNQ13 (Starbro Sport Tech) y MOV2UNQ13 (Movens). Cada tramo tiene su originador, su importe y su vencimiento.","fuentes":["https://tokens.liqi.com.br/tokens","https://tokens.liqi.com.br/tokens/PEDU?tranche=PEDUUNQ09"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"Liqi Digital Assets (Brasil)"},{"etiqueta":"Qué se adquiere","valor":"Certificados de recebíveis tokenizados: derecho a cobrar los pagos de un crédito a una empresa"},{"etiqueta":"Moneda","valor":"BRL"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Desde R$ 25 (una unidad de PEDUUNQ09)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://tokens.liqi.com.br/tokens/PEDU?tranche=PEDUUNQ09","alcance":"Ficha del tramo PEDUUNQ09 en Liqi: precio unitario R$ 25,00."},{"etiqueta":"Acceso desde España","valor":"Sin confirmar: Liqi no publica si admite residentes fuera de Brasil","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://tokens.liqi.com.br/tokens","alcance":"Web en portugués y en reales."},{"etiqueta":"Salida","valor":"Al vencimiento de cada tramo (2027 a 2028); no consta mercado secundario","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://tokens.liqi.com.br/tokens","alcance":"Lista de ofertas de Liqi con el vencimiento de cada tramo."},{"etiqueta":"Tramos en captación","valor":"7 (PEDUUNQ09, PSALES01UNQ06, MTGINCUNQ17, SCUNQ20, CLFIXUNQ17, STBROUNQ13 y MOV2UNQ13)","fechaDato":"2026-11-26","fechaConsulta":"2026-11-26","fuente":"https://tokens.liqi.com.br/tokens","alcance":"Lista de ofertas de Liqi: «Em captação»."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'finexity-bono-2026-2030-serie-b','rendimiento','FINEXITY: bono tokenizado 2026/2030 (serie B) a Euribor + 6 %, con un mínimo del 7 %','finexity','FINEXITY','credito-privado','DE','Bono de Finexity AG, empresa alemana que cotiza en Xetra, emitido como criptovalor (serie B): cupón semestral del Euribor a 6 meses + 6 %, con un mínimo del 7 % anual, y devolución al 100 % el 27/11/2030. Se ofrece al público solo en Alemania.','https://finexity-group.com/investor-relations/bond-2026-2030','2026-11-26'::date,7,false,false,true,true,null,'{"mostrada":"7,00 % mínimo","literal":"Cupón = Euribor a 6 meses + 6,00 %, con un mínimo del 7,00 % anual y sin tope, pagado cada semestre, según la hoja de términos (consultada el 26/11/2026). Antes de costes: el KID prevé hasta un 5 % de entrada y un 1,25 % al año."}'::jsonb,null,'[{"etiqueta":"Mínimo","valor":"1.000 EUR"},{"etiqueta":"Emisor","valor":"Finexity AG (Hamburgo); cotiza en Xetra"},{"etiqueta":"ISIN","valor":"DE000A5GS8B3 (serie B, criptovalor según la ley alemana eWpG)"},{"etiqueta":"Plazo","valor":"27/11/2026 a 27/11/2030; devolución al 100 %"},{"etiqueta":"Importe","valor":"Hasta 4,5 M EUR entre las series A y B"},{"etiqueta":"Costes (KID)","valor":"Entrada hasta el 5,00 %; 1,25 % anual para el distribuidor"},{"etiqueta":"Riesgo KID","valor":"6 de 7"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"La oferta pública es solo en Alemania y no tiene folleto: comprueba si la puedes suscribir desde tu país.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Bono sin garantía y sin protección de depósitos: si Finexity AG, que según la hoja de términos aún no es rentable, no paga, puedes perderlo todo.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Los costes del KID (hasta un 5 % de entrada y un 1,25 % al año) reducen lo que cobras.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"No hay mercado secundario líquido y no puedes pedir la devolución antes; el emisor sí puede amortizarlo desde 2027.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"La serie B se guarda en un wallet: hay riesgos técnicos de custodia.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://finexity-group.com/investor-relations/bond-2026-2030","https://content.finexity.com/hubfs/documents/finexity-group/FINEXITY-Group_Bond-2026-2030_Term-Sheet_EN.pdf","https://content.finexity.com/hubfs/documents/finexity-group/Bond-2026-2030/FINEXITY_BIB_Anleihe26_30_ISIN_B.pdf"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Bono 2026/2030 de Finexity AG (Hamburgo, HRB 153232), sénior y sin garantía, de ley alemana. La serie B (ISIN DE000A5GS8B3) es un criptovalor registrado por Cashlink y custodiado por Tangany. Paga cada 27/05 y 27/11 el Euribor a 6 meses más un 6,00 %, con un mínimo del 7,00 % anual, y se devuelve al 100 % el 27/11/2030. Importe de hasta 4,5 millones de euros entre las dos series; oferta pública solo en Alemania, sin folleto, del 06/11/2026 al 05/11/2027.","fuentes":["https://finexity-group.com/investor-relations/bond-2026-2030","https://content.finexity.com/hubfs/documents/finexity-group/FINEXITY-Group_Bond-2026-2030_Term-Sheet_EN.pdf","https://content.finexity.com/hubfs/documents/finexity-group/Bond-2026-2030/FINEXITY_BIB_Anleihe26_30_ISIN_B.pdf"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"FINEXITY (Finexity AG)"},{"etiqueta":"Emisor","valor":"Finexity AG, Hamburgo (HRB 153232)"},{"etiqueta":"Qué se adquiere","valor":"Un bono sénior sin garantía; la serie B, como criptovalor en un wallet"},{"etiqueta":"Moneda","valor":"EUR"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Desde 1.000 €","fechaDato":"2026-11-06","fechaConsulta":"2026-11-26","fuente":"https://content.finexity.com/hubfs/documents/finexity-group/FINEXITY-Group_Bond-2026-2030_Term-Sheet_EN.pdf","alcance":"Hoja de términos del bono 2026/2030."},{"etiqueta":"Acceso desde España","valor":"No disponible desde España: oferta pública solo en Alemania","fechaDato":"2026-11-06","fechaConsulta":"2026-11-26","fuente":"https://content.finexity.com/hubfs/documents/finexity-group/FINEXITY-Group_Bond-2026-2030_Term-Sheet_EN.pdf","alcance":"Hoja de términos: «Public offer in Germany only»."},{"etiqueta":"Salida","valor":"Al vencimiento (27/11/2030); sin mercado secundario líquido","fechaDato":"2026-11-06","fechaConsulta":"2026-11-26","fuente":"https://content.finexity.com/hubfs/documents/finexity-group/FINEXITY-Group_Bond-2026-2030_Term-Sheet_EN.pdf","alcance":"Hoja de términos: sin derecho a pedir la devolución anticipada; el emisor puede amortizar desde 2027."},{"etiqueta":"Riesgo (KID)","valor":"6 de 7","fechaDato":"2026-11-04","fechaConsulta":"2026-11-26","fuente":"https://content.finexity.com/hubfs/documents/finexity-group/Bond-2026-2030/FINEXITY_BIB_Anleihe26_30_ISIN_B.pdf","alcance":"KID de la serie B (04/11/2026)."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'groma-real-estate-trust','rendimiento','Groma Real Estate Trust: REIT de pisos en EE. UU. con acciones en cadena (GromaCoin)','groma','Groma','inmobiliario','US','Fondo inmobiliario (REIT) de 160 edificios y 725 viviendas en ciudades de EE. UU. Las acciones se pueden tener en cadena como GromaCoin; en el 3T 2026 valían 1,07 USD y repartieron el equivalente a un 3,97 % anual.','https://invest.groma.com/','2026-11-26'::date,7,false,null,false,false,null,'{"mostrada":"3,97 %","literal":"Reparto del 3T 2026 (1,0625 centavos por acción) pasado a tasa anual, según Groma (consultado el 26/11/2026). Es un reparto pasado, no un tipo fijo: puede bajar o suspenderse."}'::jsonb,null,'[{"etiqueta":"Precio por acción","valor":"1,07 USD (3T 2026; 1,00 USD al inicio)"},{"etiqueta":"Patrimonio neto estimado","valor":"94,6 millones USD (3T 2026)"},{"etiqueta":"Inmuebles","valor":"160 edificios y 725 viviendas; 97 % de ocupación en los estabilizados"},{"etiqueta":"Cómo se invierte","valor":"Acreditados: compra directa (Reg D 506(c)); resto: campaña en Wefunder (Reg CF)"},{"etiqueta":"Registro","valor":"Libro oficial de acciones en Colonial Stock Transfer; GromaCoin lo refleja en cadena"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Oferta de EE. UU. con exenciones de la SEC, sin folleto ni KID europeos; la CNMV no la supervisa.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Es un REIT no cotizado: su web no explica cómo vender las acciones, así que la salida puede ser difícil.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"El reparto pasado no asegura el futuro y el precio por acción lo calcula la propia gestora.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"En dólares: riesgo de cambio frente al euro.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Groma no publica si admite inversores de fuera de EE. UU.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://invest.groma.com/","https://www.gromareit.com/"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Groma NAV REIT, Inc. (Maryland) compra y gestiona edificios de pisos pequeños y medianos en ciudades de EE. UU. Con datos del 3T 2026: 160 edificios, 725 viviendas, 97 % de ocupación en los estabilizados, patrimonio neto estimado de 94,6 millones de dólares y acción a 1,07 USD (empezó en 1,00). Los acreditados compran directamente (Reg D 506(c)) y los no acreditados, solo por su campaña en Wefunder (Reg CF). Las acciones se pueden tener en cadena como GromaCoin; el libro oficial lo lleva Colonial Stock Transfer.","fuentes":["https://invest.groma.com/","https://www.gromareit.com/"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"Groma"},{"etiqueta":"Emisor","valor":"Groma NAV REIT, Inc. (Maryland, EE. UU.)"},{"etiqueta":"Qué se adquiere","valor":"Acciones del REIT, que se pueden tener en cadena como GromaCoin"},{"etiqueta":"Moneda","valor":"USD"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Sin mínimo publicado en su web","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://invest.groma.com/","alcance":"Página de inversión de Groma."},{"etiqueta":"Acceso desde España","valor":"Sin confirmar: oferta de EE. UU. con exenciones de la SEC","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.gromareit.com/","alcance":"Reg D 506(c) para acreditados y Reg CF en Wefunder."},{"etiqueta":"Salida","valor":"No consta en su web cómo vender: es un REIT no cotizado","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://www.gromareit.com/","alcance":"Web de Groma Real Estate Trust."},{"etiqueta":"Reparto del 3T 2026","valor":"1,0625 centavos por acción (3,97 % anualizado)","fechaDato":"2026-09-30","fechaConsulta":"2026-11-26","fuente":"https://www.gromareit.com/","alcance":"Web de Groma Real Estate Trust."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('7f745c7d-5a25-2385-9e6c-d855a22c9d02'::uuid,'securitize-hinc','rendimiento','HINC: fondo tokenizado de bonos de alto rendimiento de Neuberger Berman (Securitize)','securitize','Securitize','credito-privado','US','Fondo tokenizado que invierte en bonos de alto rendimiento de EE. UU. y CLO, gestionado por Neuberger Berman y distribuido por Securitize. Solo para inversores acreditados y cualificados, desde 100.000 USD.','https://securitize.io/hinc','2026-11-26'::date,7,false,false,false,true,null,null,null,'[{"etiqueta":"Mínimo","valor":"100.000 USD"},{"etiqueta":"Quién puede invertir","valor":"Solo inversores acreditados (AI) y compradores cualificados (QP); no particulares de EE. UU."},{"etiqueta":"Gestora","valor":"Neuberger Berman"},{"etiqueta":"Comisiones","valor":"Gestión 0,50 %; gastos totales con tope del 0,60 % anual"},{"etiqueta":"Reembolso","valor":"Peticiones diarias (corte 14:00 ET); pago objetivo T+1, sin garantía"},{"etiqueta":"Rendimiento bruto de la cartera modelo (15/07/2026)","valor":"7,62 %; no es la rentabilidad del fondo"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Solo para inversores profesionales o acreditados con 100.000 USD o más: no es para particulares.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"Bonos de alto rendimiento y CLO: más riesgo de impago que la deuda pública; puedes perder dinero.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"El pago del reembolso en T+1 es un objetivo y puede tardar más si los activos se venden mal.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"},{"texto":"En dólares o USDC: riesgo de cambio y, con USDC, riesgo de la stablecoin.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-26"}]'::jsonb,'actual'::rwadar_catalogo.estado_oferta,'["https://securitize.io/hinc"]'::jsonb,false,'{"revisadaEl":"2026-11-26","descripcion":"Neuberger Securitize High Income Tokenized Fund (HINC): fondo tokenizado que invierte sobre todo en bonos de alto rendimiento de EE. UU. y el resto en CLO, préstamos bancarios y otra renta fija de alto rendimiento, sin apalancamiento. Gestiona Neuberger Berman; Securitize lo distribuye. Mínimo 100.000 USD; solo para inversores acreditados y compradores cualificados, y no para particulares de EE. UU. Comisión de gestión 0,50 % con gastos totales limitados al 0,60 % anual.","fuentes":["https://securitize.io/hinc"],"caracteristicas":[{"etiqueta":"Proveedor","valor":"Securitize"},{"etiqueta":"Gestora","valor":"Neuberger Berman"},{"etiqueta":"Qué se adquiere","valor":"Participaciones tokenizadas de un fondo de renta fija de alto rendimiento"},{"etiqueta":"Moneda","valor":"USD o USDC"}],"referencias":[{"etiqueta":"Mínimo de inversión","valor":"Desde 100.000 USD","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://securitize.io/hinc","alcance":"Ficha de HINC en Securitize."},{"etiqueta":"Acceso desde España","valor":"No disponible para particulares: solo acreditados o cualificados","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://securitize.io/hinc","alcance":"Ficha de HINC: «Investor Qualification: AI and QP»."},{"etiqueta":"Reembolso","valor":"Diario, con pago objetivo T+1 (no garantizado)","fechaDato":null,"fechaConsulta":"2026-11-26","fuente":"https://securitize.io/hinc","alcance":"Ficha de HINC en Securitize."}]}'::jsonb,'principales') on conflict (revision_id,slug) do nothing;
